const MM_TO_IN = 25.4;
const TEMPLATE_L = 35.6 / MM_TO_IN; // inches
const TEMPLATE_W = 35.6 / MM_TO_IN; // inches
const TEMPLATE_H = 121.6 / MM_TO_IN; // inches

function transformPoint(origX_mm, origY_mm, L, W, H, thickness) {
  const origX = origX_mm / MM_TO_IN;
  const origY = origY_mm / MM_TO_IN;

  let x;
  if (origX <= 22.8 / MM_TO_IN) {
    x = origX; // glue flap area
  } else if (origX <= 58.4 / MM_TO_IN) {
    x = 22.8 / MM_TO_IN + (origX - 22.8 / MM_TO_IN) * (L / TEMPLATE_L);
  } else if (origX <= 94.0 / MM_TO_IN) {
    x = 22.8 / MM_TO_IN + L + (origX - 58.4 / MM_TO_IN) * (W / TEMPLATE_W);
  } else if (origX <= 129.6 / MM_TO_IN) {
    x = 22.8 / MM_TO_IN + L + W + (origX - 94.0 / MM_TO_IN) * (L / TEMPLATE_L);
  } else if (origX <= 164.7 / MM_TO_IN) {
    x = 22.8 / MM_TO_IN + 2 * L + W + (origX - 129.6 / MM_TO_IN) * ((W - thickness) / TEMPLATE_W);
  } else {
    x = 22.8 / MM_TO_IN + 2 * L + 2 * W - thickness + (origX - 164.7 / MM_TO_IN);
  }

  let y;
  if (origY <= 62.6 / MM_TO_IN) {
    y = 62.6 / MM_TO_IN - (62.6 / MM_TO_IN - origY) * (W / TEMPLATE_W); // Top flaps scale by W
  } else if (origY <= 184.2 / MM_TO_IN) {
    y = 62.6 / MM_TO_IN + (origY - 62.6 / MM_TO_IN) * (H / TEMPLATE_H); // Main body scales by H
  } else {
    y = 62.6 / MM_TO_IN + H + (origY - 184.2 / MM_TO_IN) * (W / TEMPLATE_W); // Bottom flaps scale by W
  }

  return { x, y };
}

