function transformSVGPath(pathStr, L, W, H, thickness) {
  return pathStr.replace(/([A-Za-z])([^A-Za-z]*)/g, (match, cmd, args) => {
    if (cmd.toUpperCase() === 'Z') return cmd;
    const nums = args.match(/-?\d*\.?\d+/g);
    if (!nums) return match;
    const newNums = [];
    for (let i = 0; i < nums.length; i += 2) {
      if (nums[i] !== undefined && nums[i+1] !== undefined) {
        const p = transformPoint(parseFloat(nums[i]), parseFloat(nums[i+1]), L, W, H, thickness);
        newNums.push(p.x + ',' + p.y);
      }
    }
    return cmd + newNums.join(' ');
  });
}

function buildLinePaths(segments, L, W, H, thickness) {
  return segments.map(seg => {
    if (Array.isArray(seg)) {
      const [x1, y1, x2, y2] = seg;
      const a = transformPoint(x1, y1, L, W, H, thickness);
      const b = transformPoint(x2, y2, L, W, H, thickness);
      return `M ${a.x},${a.y} L ${b.x},${b.y}`;
    } else {
      return transformSVGPath(seg, L, W, H, thickness);
    }
  });
}

function buildFoldLines(segments, L, W, H, thickness) {
  return segments.filter(s => Array.isArray(s)).map(([x1, y1, x2, y2]) => {
    const a = transformPoint(x1, y1, L, W, H, thickness);
    const b = transformPoint(x2, y2, L, W, H, thickness);
    return { x1: a.x, y1: a.y, x2: b.x, y2: b.y };
  });
}

export function generateCosmeticBoxDieline({ L, W, H, T = 0.5 }) {
  const nL = Number(L);
  const nW = Number(W);
  const nH = Number(H);
  const thickness = Number(T);

  const cutPaths = buildLinePaths(CUT_SEGMENTS, nL, nW, nH, thickness);
  const foldLines = buildFoldLines(FOLD_SEGMENTS, nL, nW, nH, thickness);
  const bleedPaths = buildLinePaths(BLEED_SEGMENTS, nL, nW, nH, thickness);

  let maxX = -Infinity, maxY = -Infinity, minX = Infinity, minY = Infinity;
  for (const seg of [...CUT_SEGMENTS, ...FOLD_SEGMENTS, ...BLEED_SEGMENTS]) {
    if (Array.isArray(seg)) {
      const [sx1, sy1, sx2, sy2] = seg;
      for (const p of [transformPoint(sx1, sy1, nL, nW, nH, thickness), transformPoint(sx2, sy2, nL, nW, nH, thickness)]) {
        if (p.x > maxX) maxX = p.x; if (p.y > maxY) maxY = p.y;
        if (p.x < minX) minX = p.x; if (p.y < minY) minY = p.y;
      }
    }
  }

  const x1 = 22.8 / 25.4;
  const x2 = x1 + nL;
  const x3 = x2 + nW;
  const x4 = x3 + nL;
  const x5 = x4 + nW - thickness;

  const yTop = 62.6 / 25.4;
  const yBot = yTop + nH;

  return {
    width: maxX, height: maxY, minX, minY,
    cutPaths, bleedPaths, foldLines,
    dimensions: { 
      L: nL, W: nW, H: nH, T: thickness, 
      template: { L: TEMPLATE_L, W: TEMPLATE_W, H: TEMPLATE_H },
      x1, x2, x3, x4, x5, yTop, yBot
    },
  };
}